import{_ as a,o as e,c as d,a2 as r}from"./chunks/framework.D7EuCHIT.js";const p=JSON.parse('{"title":"配置排错与迁移","description":"","frontmatter":{},"headers":[],"relativePath":"config/troubleshooting.md","filePath":"config/troubleshooting.md","lastUpdated":1791751912000}'),o={name:"config/troubleshooting.md"};function n(i,t,s,h,l,c){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="配置排错与迁移" tabindex="-1">配置排错与迁移 <a class="header-anchor" href="#配置排错与迁移" aria-label="Permalink to &quot;配置排错与迁移&quot;">​</a></h1><table tabindex="0"><thead><tr><th>现象</th><th>排查</th></tr></thead><tbody><tr><td>行号语法错误</td><td>双引号、转义、行内注释、完整 TOML 不支持语法</td></tr><tr><td>bad type</td><td>将布尔写成字符串，或数字写成引号字符串</td></tr><tr><td>invalid configuration</td><td>范围或跨字段关系；查看 宿主返回的校验结果</td></tr><tr><td>未生效却没报错</td><td>未知键无消费路径、外部/内部根优先、插件替换默认实现</td></tr><tr><td>修改了其他语言文件没变化</td><td>当前默认只加载实际指定文案文件</td></tr><tr><td>颜色透明度不对</td><td>八位格式是 AARRGGBB</td></tr><tr><td>多个表重复</td><td>合并到现有表，避免重复键依赖</td></tr><tr><td>改大字体后遮挡</td><td>布局和可用宽度也需验收，不只字重/字号</td></tr></tbody></table><h2 id="迁移" tabindex="-1">迁移 <a class="header-anchor" href="#迁移" aria-label="Permalink to &quot;迁移&quot;">​</a></h2><p>插件 schema 可声明 previous_key 和 schema_version，宿主优先新键，旧键在缺少新键时迁移。保存用户旧配置，不要因为版本更新直接删目录。</p><p>新插件参数通过 schema 声明、读取并测试，不能用不存在的宿主默认键代替。不要只在 README 写“支持”而实际没有读取。文档生成器会覆盖默认键清单，但复杂语义变化仍需人工审查教程。</p><h2 id="反馈材料" tabindex="-1">反馈材料 <a class="header-anchor" href="#反馈材料" aria-label="Permalink to &quot;反馈材料&quot;">​</a></h2><p>提供最小覆盖片段、版本、活动插件及错误，不发送完整含敏感 URL/token 的个人配置。参考公钥是公开材料，私钥和签名密码不是配置调参内容。</p>',7)])])}const u=a(o,[["render",n]]);export{p as __pageData,u as default};
